import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { HttpClient, HttpParams } from '@angular/common/http';

export interface Client {
  clientId: number;
  numeroClient: string;
  nom: string;
  prenom: string;
  telephone: string;
  email: string;
  adresseInstallation: string;
}

export interface Reclamation {
  id: number;
  reference: string;
  statut: 'OUVERTE' | 'EN_COURS_IA' | 'RESOLUE_PAR_IA' | 'ESCALADEE_SUPPORT' | 'CLOTUREE';
  priorite: 'BASSE' | 'NORMALE' | 'HAUTE';
  description: string;
  categorieCode: string;
  categorieLibelle: string;
  sousCategorieCode: string;
  sousCategorieLibelle: string;
  dateCreation: string;
  dateMiseAJour: string;
}

// Structure exacte de chaque élément du tableau "content"
export interface ReclamationItem {
  reclamation: Reclamation;
  client: Client;
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

const API_URL = 'http://localhost:8080/api';

@Component({
  selector: 'app-zone',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
   templateUrl: './zone.component.html',
   styleUrls: ['./zone.component.css']
})

export class ZoneComponent implements OnInit{
private http = inject(HttpClient);
  private readonly url = `${API_URL}/reclamations`;

  // Liste des items (Réclamation + Client)
  items: ReclamationItem[] = [];
  loading: boolean = false;
  errorMessage: string = '';

  // Filtres & Pagination
  searchTerm: string = '';
  selectedStatus: string = 'TOUS';
  page: number = 0;
  size: number = 10;
  totalPages: number = 0;

  // Gestion de la Modale Client
  isClientModalOpen: boolean = false;
  selectedClient: Client | null = null;
  selectedReclamationRef: string = '';

  ngOnInit(): void {
    this.chargerReclamations();
  }

  chargerReclamations(): void {
    this.loading = true;
    const params = new HttpParams().set('page', this.page).set('size', this.size);

    this.http.get<Page<ReclamationItem>>(this.url, { params }).subscribe({
      next: (data) => {
        this.items = data.content || [];
        this.totalPages = data.totalPages || 0;
        this.loading = false;
      },
      error: (err) => {
        console.error('Erreur chargement réclamations', err);
        this.errorMessage = 'Impossible de charger les données depuis le serveur.';
        this.loading = false;
      }
    });
  }

  // Ouvrir la modale avec les infos du client cliqué
  openClientDetails(client: Client, reclamationRef: string): void {
    this.selectedClient = client;
    this.selectedReclamationRef = reclamationRef;
    this.isClientModalOpen = true;
  }

  closeClientModal(): void {
    this.isClientModalOpen = false;
    this.selectedClient = null;
  }

  get filteredItems(): ReclamationItem[] {
    return this.items.filter(item => {
      const rec = item.reclamation;
      const cli = item.client;

      const search = this.searchTerm.toLowerCase();
      const matchesSearch = 
        rec.reference.toLowerCase().includes(search) ||
        cli.nom.toLowerCase().includes(search) ||
        cli.prenom.toLowerCase().includes(search) ||
        cli.numeroClient.toLowerCase().includes(search) ||
        rec.sousCategorieLibelle.toLowerCase().includes(search);

      const matchesStatus = 
        this.selectedStatus === 'TOUS' || 
        rec.statut === this.selectedStatus;

      return matchesSearch && matchesStatus;
    });
  }
}
